=== DamageUpAtMaxHealth.cs
     1	using UnityEngine;
     2	
     3	public class DamageUpAtMaxHealth : ModWithHP
     4	{
     5		public static string staticID = "DamageUpAtMaxHealth";
     6	
     7		private NumVarStatMod damageMod;
     8	
     9		protected override string ExtraInfo => PercentToStr(damageMod, "+");
    10	
    11		public DamageUpAtMaxHealth()
    12		{
    13			ID = staticID;
    14			category = Category.Offense;
    15			destroyOnDrop = true;
    16			comparisonType = IntComparisonType.GreaterThanEquals;
    17			HPThreshold = 1f;
    18			damageMod = new NumVarStatMod(ID, 0.2f, 10, VarStatModType.Multiplicative);
    19		}
    20	
    21		public override void Activate()
    22		{
    23			if (SetParentAsPlayer())
    24			{
    25				parentPlayer.health.RestoreHealth(0, showDisplayText: true, playSound: true, fullyRestoreHealth: true);
    26				Object.Instantiate(HealthPowerup.EffectPrefab, parentPlayer.transform.position, Quaternion.identity, parentPlayer.transform);
    27			}
    28			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
    29			base.Activate();
    30		}
    31	
    32		public override void Deactivate()
    33		{
    34			base.Deactivate();
    35			RemoveFromItemBar();
    36			if (parentPlayer != null)
    37			{
    38				parentPlayer.newItemNoticeUI.Display(TextManager.GetItemName(ID), IconManager.GetItemIcon(ID), null, isSkill: false, isSignature: false, isEmpowered: false, acquired: false);
    39			}
    40		}
    41	
    42		public override void ActivatePowerup()
    43		{
    44			base.ActivatePowerup();
    45			UpdateItemBar(ItemStatusBar.ItemState.Active);
    46			SetModStatus();
    47		}
    48	
    49		public override void DeactivatePowerup()
    50		{
    51			base.DeactivatePowerup();
    52			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
    53			SetModStatus(givenStatus: false);
    54		}
    55	
    56		private void SetModStatus(bool givenStatus = true)
    57		{
    58			StatManager.ModifyAllStatData(damageMod, parentSkillCategory, StatData.damageStr, IgnoreStatusConditional, givenStatus);
    59		}
    60	}
=== DamageUpClearInventory.cs
     1	public class DamageUpClearInventory : Item
     2	{
     3		public static string staticID = "DamageUpClearInventory";
     4	
     5		private NumVarStatMod damageMod;
     6	
     7		public int itemCount;
     8	
     9		protected override string ExtraInfo => PercentToStr(damageMod, "+");
    10	
    11		public DamageUpClearInventory()
    12		{
    13			ID = staticID;
    14			category = Category.Offense;
    15			isCursed = true;
    16			damageMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
    17		}
    18	
    19		public override void Activate()
    20		{
    21			SetModStatus(givenStatus: true);
    22		}
    23	
    24		public override void Deactivate()
    25		{
    26			SetModStatus(givenStatus: false);
    27		}
    28	
    29		private void SetModStatus(bool givenStatus)
    30		{
    31			if (!SetParentAsPlayer())
    32			{
    33				return;
    34			}
    35			if (givenStatus)
    36			{
    37				itemCount = 1;
    38				foreach (Item value in parentPlayer.inventory.itemDict.Values)
    39				{
    40					if (value != null && !value.isCursed)
    41					{
    42						if (value.isGroupItem)
    43						{
    44							itemCount += (value as GroupItem).Count;
    45							(value as GroupItem).HandleDrop(ignoreDrop: true);
    46						}
    47						else
    48						{
    49							itemCount++;
    50						}
    51					}
    52				}
    53				damageMod.modValue = (float)itemCount * 0.05f;
    54				parentPlayer.inventory.ClearInventory(keepHubOnly: false, keepCursed: true);
    55			}
    56			StatManager.ModifyAllStatData(damageMod, parentSkillCategory, StatData.damageStr, IgnoreStatusConditional, givenStatus);
    57		}
    58	}
