=== DamageUpNoEnemyKnockback.cs
     1	using System;
     2	using UnityEngine;
     3	
     4	public class DamageUpNoEnemyKnockback : Item
     5	{
     6		public static string staticID = "DamageUpNoEnemyKnockback";
     7	
     8		private NumVarStatMod damageMod;
     9	
    10		private BoolVarStatMod kbMod;
    11	
    12		private NumVarStatMod playerSpeedMod;
    13	
    14		private Enemy curEnemy;
    15	
    16		protected override string ExtraInfo => PercentToStr(damageMod, "+") + " | " + PercentToStr(playerSpeedMod, "-");
    17	
    18		public DamageUpNoEnemyKnockback()
    19		{
    20			ID = staticID;
    21			category = Category.Offense;
    22			isCursed = true;
    23			damageMod = new NumVarStatMod(ID, 0.2f, 10, VarStatModType.Multiplicative);
    24			playerSpeedMod = new NumVarStatMod(ID, -0.2f, 10, VarStatModType.Multiplicative);
    25			kbMod = new BoolVarStatMod(ID, newModValue: true, 1);
    26		}
    27	
    28		public override void Activate()
    29		{
    30			SetModStatus(givenStatus: true);
    31		}
    32	
    33		public override void Deactivate()
    34		{
    35			SetModStatus(givenStatus: false);
    36		}
    37	
    38		private void SetModStatus(bool givenStatus)
    39		{
    40			if (!SetParentAsPlayer())
    41			{
    42				return;
    43			}
    44			StatManager.ModifyAllStatData(damageMod, parentSkillCategory, "damage", IgnoreStatusConditional, givenStatus);
