schema: reverse-kit-record/1
game: wol
status: draft
collection: relic_catalog
system:
  id: '15'
  slug: relics
  title: Предметы/реликвии (система и каталог)
goal: "Каталог реликвий группы «урон»: для каждого предмета видно условие действия, величину прибавки или штрафа, тир, базовую цену и флаги. Нужен, чтобы сравнивать, как условные и проклятые варианты распределены по тирам."
rules: []
catalog:
  - id: pristine_might
    kind: relic
    own_name: "реликвия: урон при полном HP"
    numbers:
      damage_bonus: {value: 20, unit: "%", note: "множ., арканы без статусов"}
      hp_threshold: {value: 100, unit: "% макс. HP", note: "включительно"}
      tier: {value: 1, unit: "тир"}
      base_price: {value: 12, unit: "база цены", note: "золото = база × 25"}
    behavior: "При подборе разово восстанавливает HP владельца до максимума. Пока HP на максимуме или выше, урон арканов без статусов растёт. При выбросе предмет безвозвратно исчезает, игрок видит уведомление."
    source_ref: "DamageUpAtMaxHealth.cs:18"
    tags: ["исчезает при выбросе"]

  - id: purge_for_might
    kind: relic
    own_name: "проклятие: сжечь инвентарь ради урона"
    numbers:
      damage_per_burned: {value: 5, unit: "%", note: "множ., за каждую уничтоженную реликвию; арканы без статусов"}
    behavior: "Проклятая. При подборе уничтожает все непроклятые реликвии владельца, включая реликвии только для хаба; части групп уничтожаются без выброса. Считается число уничтоженных: сам предмет +1, группа по числу частей. Урон растёт за каждую уничтоженную реликвию, проклятые остаются."
    source_ref: "DamageUpClearInventory.cs:16, 53"
    tags: ["проклятая"]

  - id: stagger_less_might
    kind: relic
    own_name: "проклятие: меньше оглушений и отбрасываний"
    numbers:
      damage_bonus: {value: 33, unit: "%", note: "множ., арканы без статусов"}
      hitstun_change: {value: -70, unit: "%", note: "множ., длительность оглушения врагов от ударов"}
      knockback_change: {value: -70, unit: "%", note: "множ., отбрасывание врагов"}
    behavior: "Проклятая. Урон арканов без статусов растёт на треть. Враги от ударов оглушаются и отбрасываются заметно меньше."
    source_ref: "DamageUpHitstunDown.cs:18, 22, 26"
    tags: ["проклятая", "не в пуле"]

